using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace DesktopTodo {
 public class InlineTaskEditor:Border {
  readonly App app;readonly Todo task;readonly Action close;readonly TextBox title,note,reminder;readonly ComboBox category,sub,priority,color,repeat;readonly StrictDateInput due;readonly CheckBox important,urgent,done;readonly TextBlock error;bool dirty,confirmDelete;
  public InlineTaskEditor(App owner,Todo existing,DateTime? date,int q,Action onClose){app=owner;task=existing;close=onClose;Background=Design.Paper;BorderBrush=Design.Teal;BorderThickness=new Thickness(1);CornerRadius=new CornerRadius(10);Padding=new Thickness(14);Margin=new Thickness(12);
   var root=new DockPanel();Child=root;var header=new DockPanel{Margin=new Thickness(0,0,0,10)};var cancel=Design.Button("닫기",Cancel);DockPanel.SetDock(cancel,Dock.Right);header.Children.Add(cancel);var heading=Design.Text(task==null?"할 일 추가":"할 일 수정",18);heading.FontWeight=FontWeights.Bold;header.Children.Add(heading);DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);
   var footer=new StackPanel();error=Design.Text("",11,UI.Color("#FFB5BD"));error.Margin=new Thickness(0,5,0,6);footer.Children.Add(error);var actions=UI.Row();actions.Children.Add(Design.Button("저장",()=>Save(),true));actions.Children.Add(Design.Button("취소",Cancel));if(task!=null)actions.Children.Add(Design.Button("삭제",()=>{if(!confirmDelete){confirmDelete=true;error.Text="한 번 더 삭제를 누르면 이 할 일이 삭제됩니다.";return;}app.Data.Tasks.Remove(task);close();app.Commit();}));footer.Children.Add(actions);DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);
   var form=new StackPanel();root.Children.Add(new ScrollViewer{Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled});
   AddLabel(form,"할 일 제목");title=Design.Input(task==null?"":task.Title);title.FontWeight=FontWeights.Bold;title.FontSize=16;form.Children.Add(title);
   var fields=new Grid();fields.ColumnDefinitions.Add(new ColumnDefinition());fields.ColumnDefinitions.Add(new ColumnDefinition());StackPanel left=new StackPanel{Margin=new Thickness(0,0,6,0)},right=new StackPanel{Margin=new Thickness(6,0,0,0)};Design.Put(fields,left,0,0);Design.Put(fields,right,0,1);form.Children.Add(fields);
   AddLabel(left,"카테고리");category=Combo(app.Data.Categories.ToArray(),0);category.IsEditable=true;category.Text=task==null?app.Data.Categories.FirstOrDefault()??"개인":task.Category;left.Children.Add(category);AddLabel(right,"세부 카테고리");sub=Combo(Categories.Children(app.Data,category.Text),0);sub.IsEditable=true;sub.Text=task==null?"":task.Subcategory;sub.ToolTip="세부 분류를 선택하거나 새 이름을 입력하세요.";right.Children.Add(sub);category.SelectionChanged+=(o,e)=>{string selected=category.SelectedItem as string??category.Text;sub.ItemsSource=Categories.Children(app.Data,selected);sub.Text="";};
   AddLabel(left,"마감일");due=new StrictDateInput{SelectedDate=task==null?date:task.Date,Margin=new Thickness(0,6,0,10)};left.Children.Add(due);var quick=UI.Row();quick.Children.Add(Design.Button("오늘",()=>due.SelectedDate=DateTime.Today));quick.Children.Add(Design.Button("내일",()=>due.SelectedDate=DateTime.Today.AddDays(1)));left.Children.Add(quick);
   AddLabel(right,"우선순위");priority=Combo(new[]{"낮음","보통","높음"},task==null?1:task.Priority);right.Children.Add(priority);
   important=new CheckBox{Content="중요한 일",IsChecked=task==null?q<2:task.Important,Margin=new Thickness(0,8,0,8)};urgent=new CheckBox{Content="긴급한 일",IsChecked=task==null?q%2==0:task.Urgent,Margin=new Thickness(0,0,0,8)};right.Children.Add(important);right.Children.Add(urgent);
   AddLabel(left,"카드 색상");color=Combo(TaskActions.ColorNames,task==null?0:Math.Max(0,Array.IndexOf(TaskActions.ColorKeys,task.Color)));left.Children.Add(color);AddLabel(right,"반복");repeat=Combo(new[]{"반복 안 함","매일","매주","매월"},task==null?0:Math.Max(0,Array.IndexOf(new[]{"none","daily","weekly","monthly"},task.Repeat)));right.Children.Add(repeat);
   AddLabel(form,"알림 시간 · 예: 2026-11-01 09:00");reminder=Design.Input(task==null?"":(task.Reminder??"").Replace("T"," "));form.Children.Add(reminder);AddLabel(form,"메모");note=Design.Input(task==null?"":task.Note);note.AcceptsReturn=true;note.TextWrapping=TextWrapping.Wrap;note.Height=75;form.Children.Add(note);done=new CheckBox{Content="완료",IsChecked=task!=null&&task.Done,Margin=new Thickness(0,5,0,10)};form.Children.Add(done);
   form.AddHandler(TextBox.TextChangedEvent,new TextChangedEventHandler((o,e)=>{dirty=true;confirmDelete=false;}));form.AddHandler(ComboBox.SelectionChangedEvent,new SelectionChangedEventHandler((o,e)=>{dirty=true;confirmDelete=false;}));form.AddHandler(CheckBox.ClickEvent,new RoutedEventHandler((o,e)=>dirty=true));Loaded+=(o,e)=>title.Focus();
  }
  static void AddLabel(Panel p,string text){var l=Design.Text(text,11,Design.Muted);l.Margin=new Thickness(0,5,0,0);p.Children.Add(l);}
  static ComboBox Combo(string[] items,int index){return new ComboBox{ItemsSource=items,SelectedIndex=items.Length==0?-1:Math.Min(index,items.Length-1),Margin=new Thickness(0,6,0,12),Padding=new Thickness(7)};}
  void Cancel(){close();}
  public bool PrepareClose(){if(!dirty)return true;var answer=MessageBox.Show("작성 중인 할 일을 저장하고 종료할까요?","할 일 저장",MessageBoxButton.YesNoCancel);if(answer==MessageBoxResult.Cancel)return false;if(answer==MessageBoxResult.Yes)return Save();return true;}
  internal bool Save(){if(string.IsNullOrWhiteSpace(title.Text)){error.Text="제목을 입력하세요.";return false;}DateTime? deadline;if(!DateRules.TryDate(due.Text,out deadline)){error.Text="마감일은 2026-11-01처럼 연-월-일 전체를 입력하세요.";return false;}string alarm;if(!DateRules.TryReminder(reminder.Text,out alarm)){error.Text="알림은 2026-11-01 09:00처럼 날짜와 시간을 입력하세요.";return false;}
   var before=app.Data.Tasks.ToList();var categories=app.Data.Categories.ToList();var t=task==null?new Todo():Storage.Clone(task);bool wasDone=t.Done;t.Title=title.Text.Trim();t.Category=string.IsNullOrWhiteSpace(category.Text)?"개인":category.Text.Trim();t.Subcategory=sub.Text.Trim();t.Due=deadline.HasValue?deadline.Value.ToString("yyyy-MM-dd"):"";t.Note=note.Text;t.Priority=Math.Max(0,priority.SelectedIndex);t.Color=TaskActions.ColorKeys[Math.Max(0,color.SelectedIndex)];t.Repeat=new[]{"none","daily","weekly","monthly"}[Math.Max(0,repeat.SelectedIndex)];t.Reminder=alarm;t.Important=important.IsChecked==true;t.Urgent=urgent.IsChecked==true;Categories.Ensure(app.Data,t.Category,t.Subcategory);if(task==null)app.Data.Tasks.Add(t);else{int index=app.Data.Tasks.FindIndex(x=>x.Id==task.Id);if(index<0){error.Text="파일이 외부에서 삭제되었습니다. 저장소를 다시 확인하세요.";return false;}app.Data.Tasks[index]=t;}if(wasDone!=(done.IsChecked==true))TaskActions.Complete(app.Data,t,done.IsChecked==true);if(!app.Commit()){app.Data.Tasks=before;app.Data.Categories=categories;error.Text="저장하지 못했습니다. 작성 내용은 이 화면에 남아 있습니다.";return false;}close();return true;
  }
  internal void Verify(string name="위젯에서 바로 추가",bool completed=false){title.Text=name;color.SelectedIndex=1;note.Text="인라인 편집 검사";done.IsChecked=completed;if(!Save())throw new Exception("Inline save failed");}
  internal void VerifyDateAndClose(){int before=app.Data.Tasks.Count;title.Text="날짜 검증";foreach(string text in new[]{"1","11","2026-02-30","2026-13-01","2026-1-2"}){due.Text=text;if(Save()||app.Data.Tasks.Count!=before)throw new Exception("Invalid date was saved: "+text);}due.VerifyCalendarSelection();if(app.Data.Tasks.Count!=before)throw new Exception("Choosing a date auto-saved a task");due.SelectedDate=new DateTime(2028,2,29);if(due.Text!="2028-02-29")throw new Exception("Calendar selection does not produce canonical date");Cancel();}
  internal void VerifyDelete(){var root=(DockPanel)Child;var footer=root.Children.OfType<StackPanel>().First();var buttons=footer.Children.OfType<StackPanel>().First();var delete=buttons.Children.OfType<Button>().Last();delete.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(!app.Data.Tasks.Contains(task))throw new Exception("Delete missing confirmation");delete.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(app.Data.Tasks.Contains(task))throw new Exception("Inline delete failed");}
 }
 public partial class Dashboard {
  InlineTaskEditor inlineEditor;
  public bool IsEditing {get{return inlineEditor!=null||categoryEditor!=null;}}
  public bool PrepareClose(){return inlineEditor==null||inlineEditor.PrepareClose();}
  internal void VerifyImmediateClose(){int count=app.Data.Tasks.Count;ShowInline();inlineEditor.VerifyDateAndClose();if(inlineEditor!=null||app.Data.Tasks.Count!=count)throw new Exception("Close must dismiss immediately without saving invalid drafts");}
  void ShowInline(Todo task=null,DateTime? date=null,int q=0){if(inlineEditor!=null||categoryEditor!=null)return;inlineEditor=new InlineTaskEditor(app,task,date,q,()=>{chrome.Children.Remove(inlineEditor);inlineEditor=null;});chrome.Children.Add(inlineEditor);ApplyCommandSizes();}
  internal void VerifyInline(){int count=app.Data.Tasks.Count;ShowInline();UpdateLayout();App.Capture(this,"inline-editor-preview.png");inlineEditor.Verify();if(app.Data.Tasks.Count!=count+1||app.Data.Tasks.Last().Color!="rose")throw new Exception("Inline create failed");var t=app.Data.Tasks.Last();ShowInline(t);inlineEditor.Verify("위젯에서 수정 및 완료",true);t=app.Data.Tasks.First(x=>x.Id==t.Id);if(app.Data.Tasks.Count!=count+1||!t.Done||t.Title!="위젯에서 수정 및 완료")throw new Exception("Inline edit/completion failed");ShowInline(t);inlineEditor.VerifyDelete();if(app.Data.Tasks.Count!=count)throw new Exception("Inline deletion failed");}
 }
}
